      async calculateAndUpdateOrderWeight(customerOrderId) {
        try {
          const orderItemsData = await db.select({
            productId: orderItems2.productId,
            quantity: orderItems2.quantity
          }).from(orderItems2).where(eq8(orderItems2.orderId, customerOrderId));
          if (orderItemsData.length === 0) {
            return;
          }
          let totalWeightKg = 0;
          for (const item of orderItemsData) {
            if (item.productId) {
              const productWeight = await db.select({
                grossWeight: shopProducts.grossWeight,
                netWeight: shopProducts.netWeight,
                weight: shopProducts.weight,
                // Legacy fallback
                weightUnit: shopProducts.weightUnit
              }).from(shopProducts).where(eq8(shopProducts.id, item.productId)).limit(1);
              if (productWeight.length > 0) {
                let weight = 0;
                if (productWeight[0].grossWeight) {
                  weight = parseFloat(productWeight[0].grossWeight.toString());
                } else if (productWeight[0].weight) {
                  weight = parseFloat(productWeight[0].weight.toString());
                } else {
                  continue;
                }
                if (isNaN(weight) || weight <= 0) {
                  continue;
                }
                const unit = productWeight[0].weightUnit || "kg";
                const quantity = parseFloat(item.quantity);
                let weightInKg = weight;
                if (unit === "g" || unit === "gram") {
                  weightInKg = weight / 1e3;
                } else if (unit === "ton") {
                  weightInKg = weight * 1e3;
                }
                totalWeightKg += weightInKg * quantity;
              }
            }
          }
          if (totalWeightKg > 0) {
            await db.update(orderManagement).set({
              totalWeight: totalWeightKg.toFixed(3),
              weightUnit: "kg"
            }).where(eq8(orderManagement.customerOrderId, customerOrderId));
          }
        } catch (error) {
          console.error("Error calculating order weight:", error);
        }
      }
