  app2.post("/api/ean13/validate", requireAuth, async (req, res) => {
    try {
      const { barcode } = req.body;
      if (!barcode || typeof barcode !== "string") {
        return res.status(400).json({
          success: false,
          message: "Barcode is required"
        });
      }
      if (barcode.length !== 13 || !/^\d+$/.test(barcode)) {
        return res.json({
          success: true,
          valid: false,
          message: "Invalid EAN-13 format"
        });
      }
      let sum4 = 0;
      for (let i = 0; i < 12; i++) {
        const digit = parseInt(barcode[i]);
        sum4 += i % 2 === 0 ? digit : digit * 3;
      }
      const calculatedCheckDigit = (10 - sum4 % 10) % 10;
      const providedCheckDigit = parseInt(barcode[12]);
      const isValid = calculatedCheckDigit === providedCheckDigit;
      res.json({
        success: true,
        valid: isValid,
        checkDigit: calculatedCheckDigit,
        message: isValid ? "Valid EAN-13 barcode" : "Invalid check digit"
      });
    } catch (error) {
      console.error("Error validating EAN-13:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
  app2.post("/api/admin/backup/create", requireAuth, async (req, res) => {
    try {
      const { spawn } = await import("child_process");
      const fsModule = await import("fs");
      const pathModule = await import("path");
      const timestamp15 = (/* @__PURE__ */ new Date()).toISOString().replace(/[:.]/g, "-").substring(0, 19);
      const backupDir = "./backups";
      const backupFile = `database_backup_${timestamp15}.sql`;
      const backupPath = path.join(backupDir, backupFile);
      if (!fs.existsSync(backupDir)) {
        fs.mkdirSync(backupDir, { recursive: true });
      }
      const databaseUrl = process.env.DATABASE_URL;
      if (!databaseUrl) {
        return res.status(500).json({
          success: false,
          message: "Database URL not configured"
        });
      }
      const pgDump = spawn("pg_dump", [databaseUrl, "--no-owner", "--no-privileges"]);
      const writeStream = fs.createWriteStream(backupPath);
      pgDump.stdout?.pipe(writeStream);
      let errorOutput = "";
      pgDump.stderr?.on("data", (data) => {
        errorOutput += data.toString();
      });
      pgDump.on("close", (code) => {
        if (code === 0) {
          const stats = fs.statSync(backupPath);
          res.json({
            success: true,
            message: "Backup created successfully",
            filename: backupFile,
            size: stats.size,
            timestamp: (/* @__PURE__ */ new Date()).toISOString()
          });
        } else {
          console.error("pg_dump error:", errorOutput);
          res.status(500).json({
            success: false,
            message: "Failed to create backup",
            error: errorOutput
          });
        }
      });
    } catch (error) {
      console.error("Error creating backup:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
  app2.get("/api/admin/backup/download/:filename", requireAuth, async (req, res) => {
    try {
      const { filename } = req.params;
      if (!filename.endsWith(".sql") && !filename.endsWith(".sql.gz") || filename.includes("..") || filename.includes("/")) {
        return res.status(400).json({
          success: false,
          message: "Invalid filename"
        });
      }
      const backupPath = path.join("./backups", filename);
      if (!fs.existsSync(backupPath)) {
        return res.status(404).json({
          success: false,
          message: "Backup file not found"
        });
      }
      res.setHeader("Content-Disposition", `attachment; filename="${filename}"`);
      res.setHeader("Content-Type", "application/sql");
      const fileStream = fs.createReadStream(backupPath);
      fileStream.pipe(res);
    } catch (error) {
      console.error("Error downloading backup:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
