  app2.put("/api/admin/roles/:id/permissions", requireSuperAdmin, async (req, res) => {
    try {
      const { id: id2 } = req.params;
      const { permissionIds } = req.body;
      if (!Array.isArray(permissionIds)) {
        return res.status(400).json({ success: false, message: "Permission IDs must be an array" });
      }
      const { pool: pool2 } = await Promise.resolve().then(() => (init_db(), db_exports));
      await pool2.query("BEGIN");
      try {
        await pool2.query(`DELETE FROM role_permissions WHERE role_id = $1`, [id2]);
        if (permissionIds.length > 0) {
          const values = permissionIds.map(
            (permId, index5) => `($1, $${index5 + 2})`
          ).join(", ");
          const query = `INSERT INTO role_permissions (role_id, permission_id) VALUES ${values}`;
          await pool2.query(query, [id2, ...permissionIds]);
        }
        await pool2.query("COMMIT");
        res.json({
          success: true,
          message: "Role permissions updated successfully"
        });
      } catch (error) {
        await pool2.query("ROLLBACK");
        throw error;
      }
    } catch (error) {
      console.error("Error updating role permissions:", error);
      res.status(500).json({ success: false, message: "Internal server error" });
    }
  });
