  app2.get("/api/order-management/statistics", requireAuth, async (req, res) => {
    try {
      const orders2 = await orderManagementStorage.getAllOrdersWithDetails();
      const totalOrders = orders2.length;
      const pendingOrders = orders2.filter(
        (order) => ["pending", "pending_payment", "financial_review", "warehouse_processing"].includes(order.status)
      ).length;
      const completedOrders = orders2.filter(
        (order) => ["completed", "delivered"].includes(order.status)
      ).length;
      const totalRevenue = orders2.filter((order) => ["completed", "delivered"].includes(order.status)).reduce((sum4, order) => {
        const amount = typeof order.totalAmount === "string" ? parseFloat(order.totalAmount) : order.totalAmount || 0;
        return sum4 + amount;
      }, 0);
      const averageOrderValue = totalOrders > 0 ? totalRevenue / totalOrders : 0;
      const today = /* @__PURE__ */ new Date();
      today.setHours(0, 0, 0, 0);
      const todaysOrders = orders2.filter((order) => {
        const orderDate = new Date(order.createdAt);
        orderDate.setHours(0, 0, 0, 0);
        return orderDate.getTime() === today.getTime();
      }).length;
      res.json({
        totalOrders,
        pendingOrders,
        completedOrders,
        totalRevenue,
        averageOrderValue,
        todaysOrders
      });
    } catch (error) {
      console.error("Error fetching order statistics:", error);
      res.status(500).json({
        success: false,
        message: "Internal server error"
      });
    }
  });
