  app2.get("/api/crm/customers/:id/export-pdf", requireAuth, async (req, res) => {
    try {
      const customerId = parseInt(req.params.id);
      if (isNaN(customerId)) {
        return res.status(400).json({ success: false, message: "Invalid customer ID" });
      }
      const customer = await crmStorage.getCrmCustomerById(customerId);
      if (!customer) {
        return res.status(404).json({ success: false, message: "Customer not found" });
      }
      const analytics = await crmStorage.getCustomerAnalytics(customerId);
      const activities = await crmStorage.getCustomerActivities(customerId, 20);
      const { generateCustomerPDFWithPDFMake: generateCustomerPDFWithPDFMake2 } = await Promise.resolve().then(() => (init_pdfmake_generator(), pdfmake_generator_exports));
      const pdfBuffer = await generateCustomerPDFWithPDFMake2(customer, analytics.orders || [], activities, `\u0645\u0634\u062A\u0631\u06CC ${customer.name}`);
      if (!pdfBuffer || pdfBuffer.length === 0) {
        throw new Error("Generated PDF is empty");
      }
      console.log("Customer report PDF generated successfully, size:", pdfBuffer.length, "bytes");
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="customer-report-${customerId}-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.pdf"`);
      res.setHeader("Cache-Control", "no-cache");
      res.end(pdfBuffer);
    } catch (error) {
      console.error("Error generating customer PDF:", error);
      res.status(500).json({
        success: false,
        message: "Failed to generate customer PDF report"
      });
    }
  });
